insert into tap_results select lives_ok($$select public.agri_command('snapshot',pg_temp.ctx())$$,'Snapshot works through renamed archive and credit commands');
insert into tap_results select lives_ok($$select public.agri_command('dashboard',pg_temp.ctx())$$,'Dashboard works through the production archive chain');
insert into tap_results select lives_ok($$select public.agri_command('count_workspace',pg_temp.ctx())$$,'Stock-count reads retain their authorization path');
insert into tap_results select lives_ok($$select public.agri_command('purchasing_workspace',pg_temp.ctx())$$,'Purchasing reads retain their authorization path');
insert into tap_results select is(public.agri_command('credit_book',pg_temp.ctx())->>'outstanding','0','Credit report works alongside the archive guard');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx())#>>'{historyArchive,id}',pg_temp.i(701)::text,'Owner still receives archive reconciliation metadata');
insert into tap_results select throws_ok($$select public.agri_command('partial_refund_plan',pg_temp.ctx()||jsonb_build_object('saleId',pg_temp.i(702)))$$,'22023','This TEST record was archived during store preparation. Start a new record.','Archived test IDs stay blocked from live adjustments');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.old_sale())$$,'42501','The original cashier must acknowledge this archived test sale','Even the owner cannot replay another cashier archive');
insert into tap_results select is(public.agri_command('record_sale',pg_temp.old_sale())->>'status','duplicate','Exact original archived cash retry is acknowledged without a new sale');
insert into tap_results select is(public.agri_command('record_sale',pg_temp.old_sale())->>'status','duplicate','Repeated archived retry remains idempotent');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.old_sale()||'{"total":1}'::jsonb)$$,'22023','Archived test transaction payload differs from the original','Changed archived money is refused');
insert into tap_results select is(public.agri_command('snapshot',pg_temp.ctx()||jsonb_build_object('transactionIds',jsonb_build_array(pg_temp.i(702))))#>>'{confirmedIds,0}',pg_temp.i(702)::text,'Original cashier can reconcile the archived acknowledgement');
insert into tap_results select throws_ok($$select * from app_private.archived_test_sales$$,'42501',null,'Archive remains private to the command');
insert into tap_results select throws_ok($$select public.agri_command('record_sale',pg_temp.old_sale())$$,'42501','The original cashier must acknowledge this archived test sale','Stock staff cannot turn an archive into a cash sale');
insert into tap_results select throws_ok($$select public.agri_command('credit_book',pg_temp.ctx())$$,'42501','Only authorized sales staff can access client credit','The fix does not widen credit access');
insert into tap_results select is((select count(*) from public.sales),0::bigint,'No archive check or retry creates a live sale');
insert into tap_results select is((select count(*) from public.payments),0::bigint,'No archive check or retry creates drawer cash');
insert into tap_results select is((select count(*) from public.inventory_movements),0::bigint,'No archive check or retry creates stock movements');
insert into tap_results select is((select count(*) from app_private.archived_test_sales),1::bigint,'Original archive is retained');
insert into tap_results select * from finish();select line from tap_results;
